package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_append_TriageGen1Test {

    @Test
    public void testAppend_ValidHtml_AppendsChildren() {
        Element parent = new Element(Tag.valueOf("div"), "");
        String html = "<p>Hello</p><span>World</span>";

        Element result = parent.append(html);

        // Verify return type (fluent API)
        Assert.assertSame(parent, result);

        // Verify children count (p and span)
        Assert.assertEquals(2, parent.children().size());
        Assert.assertEquals("p", parent.child(0).tagName());
        Assert.assertEquals("span", parent.child(1).tagName());

        // Verify content
        Assert.assertEquals("<div=\"\"> <p>Hello</p><span>World</span></div>", parent.outerHtml().replace("\n", "").replace("\r", "").replace(" ", ""));
        // Note: exact string comparison might vary by Jsoup version whitespace handling, 
        // but the logic checks if nodes are appended.
        Assert.assertTrue(parent.html().contains("<p>Hello</p>"));
        Assert.assertTrue(parent.html().contains("<span>World</span>"));
    }










}

