package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_append_TriageGen1Test {









    @Test
    public void testAppend_ComplexStructure_MaintainsHierarchy() {
        Element parent = new Element(Tag.valueOf("ul"), "");
        String html = "<li>Item 1</li><li>Item 2<ul><li>Sub</li></ul></li>";

        parent.append(html);

        Assert.assertEquals(2, parent.children().size());
        Assert.assertEquals("li", parent.child(0).tagName());
        Assert.assertEquals("li", parent.child(1).tagName());
        Assert.assertEquals("ul", parent.child(1).child(0).tagName());
        Assert.assertEquals("Sub", parent.child(1).child(0).child(0).text());
    }


}

package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
