import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_append_TriageGen1Test {











    @Test
    public void testAppend_FragmentWithMultipleRootNodes() {
        // The method iterates through fragment.childNodes()
        // fragment is the body, so it contains the nodes provided in the string
        Element parent = new Element(Tag.valueOf("div"), "");
        String html = "<div>Node1</div><div>Node2</div>";

        parent.append(html);

        Assert.assertEquals(2, parent.children().size());
        Assert.assertEquals("div", parent.child(0).tagName());
        Assert.assertEquals("div", parent.child(1).tagName());
    }
}
